import {QUESTION_PROGRAM_BATCH7_ACCEPTED_SOURCE_VIEWS} from "./question-program-batch7-accepted-20261112";
import {QUESTION_PROGRAM_BATCH4_ACCEPTED_SOURCE_VIEWS,QUESTION_PROGRAM_BATCH4_FROZEN_PRESERVATION} from "./question-program-batch4-accepted-20261111";
import {createHash} from "node:crypto";
import { describe, expect, it } from "vitest";
import { SYNTHETIC_CLINICAL_RELEASE } from "./synthetic-content";
import {QUESTION_STATS1_ACCEPTED_SOURCE_RELEASE} from "./question-stats1-accepted-20261108";
import {QUESTION_PROGRAM_BATCH3_ACCEPTED_SOURCE_VIEWS} from "./question-program-batch3-accepted-20261111";
import type {SyntheticClinicalCase} from "./schema";

// The owner-approved non-clinical statistics style retains exact reviewed
// presentation-only staff profiles. They never introduce patient demographics.
// Every other staff discussion keeps the original no-profile assertion.
function expectStaffProfiles(clinicalCase:SyntheticClinicalCase):void {
 const exact=[...Object.values(QUESTION_PROGRAM_BATCH7_ACCEPTED_SOURCE_VIEWS).flatMap(view=>view.cases),...QUESTION_STATS1_ACCEPTED_SOURCE_RELEASE.cases,...Object.values(QUESTION_PROGRAM_BATCH4_ACCEPTED_SOURCE_VIEWS).flatMap(view=>view.cases),...QUESTION_PROGRAM_BATCH3_ACCEPTED_SOURCE_VIEWS["topic-batch3-statistics"]!.cases].find(c=>c.id===clinicalCase.id&&
  c.participant?.kind==="employee_discussion"&&c.decisionNodes[0]!.questionVariantId===clinicalCase.decisionNodes[0]!.questionVariantId);
 if(!exact){expect(clinicalCase.approvedInstantiationProfiles,clinicalCase.id).toBeUndefined();return;}
 expect(clinicalCase.approvedInstantiationProfiles,clinicalCase.id).toEqual(exact.approvedInstantiationProfiles);
 expect(clinicalCase.approvedInstantiationProfiles).toHaveLength(1);
 for(const profile of clinicalCase.approvedInstantiationProfiles!){
  expect(profile.prototypeDemographics).toBeUndefined();expect(profile.prototypeVitalSigns).toBeUndefined();
  expect(profile.presentation).toBe(clinicalCase.presentation);expect(profile.chiefComplaint).toBe(exact.chiefComplaint);
  expect(Object.keys(profile).sort()).toEqual(["chiefComplaint","id","presentation"]);
 }
}

const MULTI_PATIENT_FRAMING = [
  /\bwhich patient\b/i,
  /\b(?:four|several|multiple) (?:stable )?(?:adults|patients)\b/i,
  /\b(?:reviewing|counseling) patients\b/i,
  /\bwhich (?:presentation|referral profile)\b/i,
];

const PATIENT_REFERENCE =
  /(?:\{patientName\}|\b(?:patient|adult|woman|man|recipient|they|she|he|\d{1,3}-year-old)\b)/i;
const STORY_CUE =
  /\b(?:asks?|wants?|requests?|reports?|returns?|arrives?|attends?|noticed|notes?|describes?|is seen|is reviewed|is offered|is invited|comes?|visits?|brings?|discuss(?:es|ing)?|reviews?|reviewing|hoping|considering|counseled|diagnosed|hypercalcemia|shows?|showing|discovered|identifies|referred|confirming|evaluated|evaluates?|assess(?:ed|ing)|wakes?|found|undergoing|preparing|prepared|presents?|has|have|had|develops?|confirms|completed|scheduled|plans|starts|persists|decides|receives|reads?|sees?|declines?|lacks?|overhears?|recognizes?|waits?|considers?|compares?|moves?|records?|measures?|tabulates?|cross-classifies|tracks?|designs?|tests?|recalls?|cannot|eats?|viene|consulta|llega|quiere|dice|pregunta|está|comprende)\b/i;
const ALTERNATE_PATIENT_CHOICE =
  /^(?:a|an|fit) (?:patient|adult|woman|man)\b/i;

function normalized(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

describe("playable one-patient narratives", () => {
  it("anchors every admitted case to one patient with a brief story", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.id.startsWith("case.l2.")) continue;
      if (clinicalCase.participant?.kind === "employee_discussion") {
        expect(clinicalCase.presentation, clinicalCase.id).toContain(
          "{patientName}",
        );
        expect(clinicalCase.presentation, clinicalCase.id).toMatch(STORY_CUE);
        expect(clinicalCase.prototypeDemographics, clinicalCase.id).toBeUndefined();
        expect(clinicalCase.prototypeVitalSigns, clinicalCase.id).toBeUndefined();
        expectStaffProfiles(clinicalCase);
        continue;
      }
      expect(clinicalCase.presentation, clinicalCase.id).toMatch(
        PATIENT_REFERENCE,
      );
      expect(clinicalCase.presentation, clinicalCase.id).toMatch(STORY_CUE);
      let patientStory=clinicalCase.presentation;
      if(clinicalCase.id==="case.topic.quality-safety-systems.specimen-observed-barrier.standalone.v1"){
        // This reviewed single-patient chart describes a batch-printing error.
        // Bind the exact background sentence before testing the patient story.
        const background="Labels for several patients had been printed together and placed at the shared collection bench. ";
        expect(patientStory).toContain(background);
        expect(createHash("sha256").update(JSON.stringify(clinicalCase)).digest("hex"))
          .toBe(QUESTION_PROGRAM_BATCH4_FROZEN_PRESERVATION.find(row=>row.caseId===clinicalCase.id)!.retainedCaseSha256);
        patientStory=patientStory.replace(background,"");
      }
      for (const pattern of MULTI_PATIENT_FRAMING) {
        expect(patientStory, clinicalCase.id).not.toMatch(
          pattern,
        );
      }
    }
  });

  it("keeps decision prompts tied to that encounter instead of restating the chart", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.id.startsWith("case.l2.")) continue;
      const firstPresentationSentence =
        clinicalCase.presentation.match(/^.*?[.!?](?:\s|$)/)?.[0] ?? "";
      for (const node of clinicalCase.decisionNodes) {
        for (const pattern of MULTI_PATIENT_FRAMING) {
          expect(node.stem, node.id).not.toMatch(pattern);
        }
        if (firstPresentationSentence.length >= 50) {
          expect(normalized(node.stem), node.id).not.toContain(
            normalized(firstPresentationSentence),
          );
        }
      }
    }
  });

  it("uses alternative findings rather than a lineup of different patients", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      for (const node of clinicalCase.decisionNodes) {
        for (const choice of node.answerChoices) {
          expect(choice.label, `${node.id}:${choice.id}`).not.toMatch(
            ALTERNATE_PATIENT_CHOICE,
          );
        }
      }
    }
  });

  it("keeps explicitly female stories attached to female chart identities", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.participant?.kind === "employee_discussion") {
        expect(clinicalCase.prototypeDemographics, clinicalCase.id).toBeUndefined();
        expectStaffProfiles(clinicalCase);
        continue;
      }
      const profiles = clinicalCase.approvedInstantiationProfiles ?? [];
      if (profiles.length > 0) {
        for (const profile of profiles) {
          if (/\b(?:woman|she|her)\b/i.test(profile.presentation)) {
            expect(profile.prototypeDemographics?.sexLabel, `${clinicalCase.id}/${profile.id}`).toBe("Female");
          }
        }
      } else if (/\b(?:woman|she|her)\b/i.test(clinicalCase.presentation)) {
        expect(clinicalCase.prototypeDemographics?.sexLabel, clinicalCase.id).toBe("Female");
      }
    }
  });
});

import {beforeProgramBatch9AcceptanceRelease,beforeProgramBatch9AcceptanceManifest,beforeProgramBatch9AcceptanceSourceBytes,beforeProgramBatch9AcceptanceCases,beforeProgramBatch9AcceptanceConcepts} from "./question-program-batch9-acceptance-test-support";
// Preserve every authoring-era exclusion/pin against its exact verified epoch.
// Batch9 independently asserts current accepted and still-withheld tuples.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { PROTOTYPE_BALANCE_RELEASE } from "../../balance-config/src/prototype-balance";
import { answerChoiceTimingRegistryEntrySchema, syntheticClinicalCaseSchema, testedConceptSchema } from "./schema";
import * as topic from "./question-intraop-asc-access-and-soft-tissue-surprises-20261112";

const root = fileURLToPath(new URL("../../../", import.meta.url));
const json = (path: string) => JSON.parse(readFileSync(`${root}${path}`, "utf8"));
const packet = json("docs/research/question-intraop-asc-access-and-soft-tissue-surprises-20261112.json");
const ledger = json("docs/research/sources-question-intraop-asc-access-and-soft-tissue-surprises-20261112.json");
const program = json("docs/research/question-intraop-program-20261112.json");
const sha = (value: unknown) => createHash("sha256").update(beforeProgramBatch9AcceptanceSourceBytes(typeof value === "string" ? value : JSON.stringify(value))).digest("hex");
const unique = (values: string[]) => expect(new Set(values).size).toBe(values.length);
const {
  ASC_ACCESS_INTRAOP_CASES: cases, ASC_ACCESS_INTRAOP_QUESTIONS: questions,
  ASC_ACCESS_INTRAOP_NODES: nodes, ASC_ACCESS_INTRAOP_CONCEPTS: concepts,
  ascAccessIntraopId: id,
} = topic;

describe("I12 revision round 1: exact PASS preservation and four bounded revisions, never clinical approval", () => {
  it("audits every assigned occurrence/definition and separates held planning work from scored verdict counts", () => {
    const assignment = program.taxonomy.find((t: { id: string }) => t.id === "I12");
    expect(packet.assignment).toEqual(assignment);
    const assignedIds = [...assignment.existingRelatedBankNodes.map((r: { recordId: string }) => r.recordId), ...assignment.retainedRecordIds, ...assignment.authoringDefinitionRecordIds];
    expect(packet.audit.map((r: { recordId: string }) => r.recordId).sort()).toEqual(assignedIds.sort());
    expect(packet.counts).toMatchObject({ inventoryRows: 131, liveOccurrences: 11, retainedNodeDefinitions: 56, authoredQuestionDefinitions: 64, keptExactDefinitions: 131, heldPlanningRows: 3, scoredVerdicts: { Keep: 128, Rewrite: 0, "Retire-and-replace": 0 } });
    for (const row of packet.audit) {
      expect(row.currentVerification.exactHashFound, row.recordId).toBe(true);
      expect(sha(row.currentVerification.exact), row.recordId).toBe(row.beforeSha256);
      expect(row.verdict).toBe("Keep"); expect(row.beforeVersion).toBeTruthy();
      expect(row.source.file).toBeTruthy(); expect(row.source.export).toBeTruthy();
      expect(row.reason.length).toBeGreaterThan(90);
      if (row.inventoryKind !== "authoringDefinitions") expect(row.retainedHeaderContexts.length, row.recordId).toBeGreaterThan(0);
      if (!row.scoredVerdictEligible) expect(row.planningDisposition).toContain("parked");
    }
  });

  it("retains exact independently passed and manager-accepted identities without creating named clinical approval", () => {
    expect(packet.frozenReferences.liveAccepted).toHaveLength(5);
    expect(packet.frozenReferences.detailed).toHaveLength(5);
    expect(packet.frozenReferences.sourceFreeze).toHaveLength(4);
    expect(packet.frozenReferences.namedClinicalApprovals).toEqual([]);
    for (const row of packet.frozenReferences.detailed) {
      expect(row.questionSha256).toMatch(/^[a-f0-9]{64}$/);
      expect(row.sourceNodeSha256).toMatch(/^[a-f0-9]{64}$/);
      expect(row.contentVersion).toBeTruthy(); expect(row.originalDecisionPaths.length).toBeGreaterThan(1);
      expect(row.independentReviews.every((r: { verdict: string }) => r.verdict === "PASS")).toBe(true);
      expect(row.clinicianReviewer).toBeNull(); expect(row.clinicalStatus).toBe("needs_clinician_review");
      for (const review of row.independentReviews) expect(sha(readFileSync(`${root}${review.path}`, "utf8"))).toBe(review.fileSha256);
    }
    for (const freeze of packet.frozenReferences.sourceFreeze) for (const file of freeze.sourceFiles) {
      expect(sha(readFileSync(`${root}${file.path}`, "utf8")), file.path).toBe(file.currentSha256);
    }
    const protectedN4 = packet.baseline.sourceInputHashes.filter((f: { file: string }) => /question-(?:n4-accepted|new-n4-round2)-20261110\.ts$/.test(f.file));
    expect(protectedN4).toHaveLength(2);
    for (const file of protectedN4) expect(sha(readFileSync(`${root}${file.file}`, "utf8"))).toBe(file.sha256);
  });

  it("preserves all assigned historical source bytes and exact retained header projections", () => {
    for (const input of packet.baseline.sourceInputHashes) expect(sha(readFileSync(`${root}${input.file}`, "utf8")), input.file).toBe(input.sha256);
    for (const row of packet.audit) for (const context of row.retainedHeaderContexts) {
      const { visibleContextSha256, origins, ...projection } = context;
      expect(sha(projection)).toBe(visibleContextSha256);
      expect(origins.length).toBeGreaterThan(0); expect(projection.presentation).toBeTruthy();
    }
    expect(packet.relatedConceptAudit).toHaveLength(12);
    expect(packet.relatedConceptAudit.some((r: { currentDefaultNodeReferences: unknown[] }) => r.currentDefaultNodeReferences.length === 0)).toBe(true);
    expect(packet.baseline.drift.assignedLiveDefinitionChecks.every((r: { nodeHashMatchesCurrent: boolean }) => r.nodeHashMatchesCurrent)).toBe(true);
  });

  it("keeps five distinct constructs additive and outside shared release authority", () => {
    expect(cases).toHaveLength(4); expect(nodes).toHaveLength(5); expect(questions).toHaveLength(5); expect(concepts).toHaveLength(5);
    unique(cases.map(c => c.id)); unique(questions.map(q => q.id)); unique(concepts.map(c => c.id));
    unique(cases.flatMap(c => c.decisionNodes.map(n => n.id)));
    const historicalConcepts = new Set(packet.audit.map((r: { conceptId: string }) => r.conceptId));
    expect(concepts.every(c => !historicalConcepts.has(c.id))).toBe(true);
    expect(packet.identityProposals.every((r: { action: string; previousConceptId: null }) => r.action === "new_construct" && r.previousConceptId === null)).toBe(true);
    expect(readFileSync(`${root}packages/clinical-content/src/index.ts`, "utf8")).not.toContain("question-intraop-asc-access-and-soft-tissue-surprises-20261112");
    expect(beforeProgramBatch9AcceptanceSourceBytes(readFileSync(`${root}packages/clinical-content/src/question-ship-manifest.ts`, "utf8"))).not.toContain("question.intraop.asc-access.");
    expect(cases.every(c => !c.routineEligible && !c.tutorialEligible)).toBe(true);
  });

  it("validates strict case/concept structures with prospective integration metadata outside cases", () => {
    for (const c of cases) {
      const checked = syntheticClinicalCaseSchema.safeParse(c);
      expect(checked.success, `${c.id}: ${checked.success ? "" : checked.error.message}`).toBe(true);
      expect(c).not.toHaveProperty("procedureFamily"); expect(c).not.toHaveProperty("mode");
      expect(c).not.toHaveProperty("procedureContext"); expect(c).not.toHaveProperty("reviewStatus");
      expect(c.requiredClinicalSetting).toBe("ambulatory_surgery"); expect(c.earliestFacilityStage).toBe(3);
      expect(c.requiredCapabilityIds).toEqual(["capability.ambulatory_or", "capability.staff.or_nurse", "capability.periop_recovery"]);
    }
    for (const c of concepts) expect(testedConceptSchema.safeParse(c).success, c.id).toBe(true);
  });

  it("keeps every new authored clinical record unapproved with randomized choices and null execution gates", () => {
    for (const record of [...questions, ...topic.ASC_ACCESS_INTRAOP_AUTHORING_CONCEPTS, ...topic.ASC_ACCESS_INTRAOP_SOURCES, ...topic.ASC_ACCESS_INTRAOP_CLAIMS, ...topic.ASC_ACCESS_INTRAOP_PROCEDURE_CONTEXT_PROPOSALS]) {
      expect(record.reviewStatus).toBe("needs_clinician_review"); expect(record.aiAssistedDrafting).toBe(true);
      expect(record.lastClinicianReview).toBeNull();
    }
    for (const q of questions) {
      expect(q.shuffleAnswers).toBe(true); expect(q.answerChoices).toHaveLength(3);
      expect(q.answerChoices.filter(a => a.isCorrect)).toHaveLength(1); unique(q.answerChoices.map(a => a.id));
    }
    for (const c of cases) for (const n of c.decisionNodes) {
      expect(n.shuffleAnswers).toBe(true); expect(n.resultGateAfter).toBeNull();
      expect(n.answerChoices.every(a => a.serviceRequest === null)).toBe(true);
    }
  });

  it("declares live procedure families honestly and holds central-access admission beyond the current ENG-I01 allowlist", () => {
    const proposals = topic.ASC_ACCESS_INTRAOP_PROCEDURE_CONTEXT_PROPOSALS;
    expect(proposals).toHaveLength(4);
    expect(proposals.filter(p => p.procedureContext.familyId === "procedure.central_venous_port_insertion")).toHaveLength(3);
    expect(proposals.filter(p => p.procedureContext.familyId === "procedure.soft_tissue_excision")).toHaveLength(1);
    for (const proposal of proposals) {
      expect(proposal.mode).toBe("live_asc_or"); expect(proposal.dependencies).toContain("ENG-I01");
      expect(proposal.newExecutedMidprocedureResult).toBe(false);
      expect(proposal.pediatricContext).toBeNull(); expect(proposal.parentCheckpoints).toBeNull();
      expect(proposal.admissionStatus).toBe("withheld_pending_independent_review_and_manager_integration");
      expect(proposal.additionalCapabilityNeeds.length).toBeGreaterThan(0);
      expect(proposal.procedureContext).toMatchObject({ version: "procedure-context.v1", mode: "live", kind: "operation", phase: "procedure" });
      expect(proposal.procedureContext.allowedIncomeLineIds).toEqual(["income.ambulatory_operation", "income.ambulatory_operation_extended"]);
      const c = cases.find(c => c.id === proposal.caseId)!;
      expect(syntheticClinicalCaseSchema.safeParse({ ...c, procedureContext: proposal.procedureContext }).success).toBe(true);
      if (proposal.procedureContext.familyId.includes("central_venous")) expect(proposal.dependencies).toContain("port_family_and_capability_integration");
    }
    const engine = readFileSync(`${root}packages/game-domain/src/procedure-context.ts`, "utf8");
    expect(engine).toContain('"procedure.soft_tissue_excision"');
    expect(engine).not.toContain('"procedure.central_venous_port_insertion"');
    expect(packet.runtimeContext.exceptions).toEqual(["Hospital access or oncologic reconstruction uses clinic chart review"]);
  });

  it("binds one named adult finite profile to each live procedure and keeps tier, acuity and progression separate", () => {
    for (const definition of topic.ASC_ACCESS_INTRAOP_CASE_DEFINITIONS) {
      expect(definition.age).toBeGreaterThanOrEqual(18); expect(definition.presentation).toContain(definition.name);
      expect(definition.presentation).toContain(`${definition.age}-year-old`);
      expect(definition.presentation).toContain(definition.sex === "Female" ? "woman" : "man");
      expect(definition.presentation).toContain("ASC operating room"); expect(definition.presentation).toContain("underway");
      expect(definition.complaint.split(/\s+/).length).toBeLessThanOrEqual(5);
      const c = cases.find(c => c.id === id("case", definition.slug))!;
      expect(c.approvedInstantiationProfiles).toHaveLength(1);
      expect(c.approvedInstantiationProfiles![0]!.prototypeDemographics).toEqual(c.prototypeDemographics);
      const context = topic.ASC_ACCESS_INTRAOP_PROCEDURE_CONTEXT_PROPOSALS.find(p => p.caseId === c.id)!;
      expect(context.educationalTier).toBe(1); expect(context.facilityProgressionLevel).toBe(3);
      expect(context.patientAcuity).toBe(definition.patientAcuity);
      for (const n of c.decisionNodes) expect(n.stem).toContain(definition.name.split(" ")[0]);
    }
    expect(packet.runtimeContext.pediatricContext).toBeNull();
    expect(packet.runtimeContext.pediatricOwnership).toContain("I23");
  });

  it("keeps the natural two-part specimen sequence distinct without enacted diagnostics or future-answer scaffolding", () => {
    const paired = cases.filter(c => c.decisionNodes.length > 1);
    expect(paired).toHaveLength(1); expect(paired[0]!.decisionNodes).toHaveLength(2);
    const [first, second] = paired[0]!.decisionNodes;
    expect(first!.explanation).not.toMatch(/oppos(?:ite|ing)|loop|newly created/);
    expect(paired[0]!.presentation).toContain("sample is planned");
    expect(second!.currentUpdate).toContain("has now been cut");
    expect(second!.currentUpdate).toContain("loose loop marks the cavity side");
    expect(second!.explanation).toContain("neither restores the earlier fragment's orientation nor establishes histological clearance");
    expect(nodes[4]!.gate.deletionTest).toContain("no offered face");
    expect(nodes[4]!.gate.sequenceCheck).toContain("no result gate");
    expect(topic.ASC_ACCESS_INTRAOP_COMPOSITION_PROPOSALS.filter(c => c.selection === "paired_only_all_concepts_unseen_or_due")).toHaveLength(1);
    expect(topic.ASC_ACCESS_INTRAOP_COMPOSITION_PROPOSALS.every(c => c.limitation.includes("future-due companion"))).toBe(true);
  });

  it("maps all offered clinical fields, keys and distractor rationales to atomic claims and reverse-linked sources", () => {
    const claims = new Map(topic.ASC_ACCESS_INTRAOP_CLAIMS.map(c => [c.id, c]));
    const sources = new Map(topic.ASC_ACCESS_INTRAOP_SOURCES.map(s => [s.id, s]));
    expect(claims.size).toBe(22); expect(sources.size).toBe(9);
    for (const n of nodes) {
      for (const claimId of n.claimIds) {
        const c = claims.get(claimId)!; expect(c, claimId).toBeTruthy(); expect(c.limitation).toBeTruthy();
        expect(c.lastCheckedOn).toBe("2026-11-12");
        for (const source of c.sourceIds) expect(sources.get(source)!.evidenceClaimIds).toContain(c.id);
      }
      const mappedFields = ledger.fieldToClaimMappings.filter((r: { questionVariantId: string }) => r.questionVariantId === id("question", n.slug));
      for (const field of ["presentation", "currentUpdate", "stem", "explanation", "learningSummary", "gate.counterfactual"]) expect(mappedFields.some((r: { field: string }) => r.field === field)).toBe(true);
      for (const a of n.choices) {
        expect(a.rationale.length).toBeGreaterThan(50); expect(a.temptation.length).toBeGreaterThan(40); expect(a.counterfactual.length).toBeGreaterThan(45);
        expect(a.claimIds.every(claimId => n.claimIds.includes(claimId))).toBe(true);
        const mapping = ledger.choiceToClaimMappings.find((r: { choiceId: string }) => r.choiceId === id("choice", `${n.slug}.${a.slug}`));
        expect(mapping.choiceLabel).toBe(a.label); expect(mapping.claimIds).toEqual(a.claimIds);
      }
    }
    for (const c of claims.values()) expect(ledger.claimToQuestionMappings.find((r: { claimId: string }) => r.claimId === c.id).questionVariantIds.length).toBeGreaterThan(0);
  });

  it("records source authority independently of rights and withholds the unresolved exact tip-target comparison", () => {
    for (const s of topic.ASC_ACCESS_INTRAOP_SOURCES) {
      expect(s.completeCitation.length).toBeGreaterThan(80); expect(s.authors.length).toBeGreaterThan(0);
      expect(s.officialUrl).toMatch(/^https:\/\//); expect(s.accessedOn).toBe("2026-11-12");
      expect(s.licenseLabel).toBeTruthy(); expect(s.reuseNotes.length).toBeGreaterThan(80); expect(s.authorityAssessment.length).toBeGreaterThan(60);
    }
    expect(ledger.withheldDisagreements).toHaveLength(1);
    expect(ledger.withheldDisagreements[0]).toMatchObject({ id: "I12-tip-target-range", status: "withheld_not_scored" });
    expect(ledger.sourceLimitations.some((s: string) => s.includes("extrapolation"))).toBe(true);
    expect(ledger.excludedOrUnusableSources.some((s: { reason: string }) => s.reason.includes("payment required"))).toBe(true);
    for (const link of topic.ASC_ACCESS_INTRAOP_SOURCE_LINKS) expect(link).toMatchObject({ target: "_blank", rel: "noopener noreferrer", referrerPolicy: "no-referrer" });
  });

  it("binds every testing alternative to an existing planned placeholder and survives answer reordering", () => {
    for (const row of topic.ASC_ACCESS_INTRAOP_TIMING_PROPOSALS) expect(answerChoiceTimingRegistryEntrySchema.safeParse(row).success).toBe(true);
    expect(topic.ASC_ACCESS_INTRAOP_TIMING_PROPOSALS.filter(r => r.classification.kind === "test_choices")).toHaveLength(1);
    expect(topic.ASC_ACCESS_INTRAOP_ORDER_PROPOSALS).toHaveLength(3);
    const testingNode = cases[0]!.decisionNodes[0]!;
    for (const reordered of [testingNode.answerChoices, [...testingNode.answerChoices].reverse(), [...testingNode.answerChoices.slice(1), testingNode.answerChoices[0]!]]) {
      for (const a of reordered) {
        const order = topic.ASC_ACCESS_INTRAOP_ORDER_PROPOSALS.find(o => o.choiceId === a.id)!;
        expect(order.choiceLabel).toBe(a.label); expect(order.questionVariantId).toBe(testingNode.questionVariantId);
        expect(PROTOTYPE_BALANCE_RELEASE.answerChoiceTimingProfiles.some(p => p.id === order.timingProfileId)).toBe(true);
        expect(order.disposition).toEqual({ kind: "not_executed", reason: "future_planned" });
        expect(order.serviceRequest).toBeNull(); expect(order.resultGateAfter).toBeNull();
        expect(order.note).toContain("not a clinical intraoperative wait");
      }
    }
    for (const c of cases) for (const n of c.decisionNodes) expect([c.presentation, n.currentUpdate, n.stem, ...n.answerChoices.map(a => a.label)].join(" ")).not.toMatch(/\b\d+\s*(minutes?|hours?|days?)\b/i);
    expect(readFileSync(`${root}packages/clinical-content/src/answer-choice-timing.ts`, "utf8")).not.toContain("question.intraop.asc-access.");
  });

  it("records concrete five-check author reasoning and keeps both clean-rule roles pending independent acceptance", () => {
    for (const n of nodes) {
      for (const [key, value] of Object.entries(n.gate)) if (key !== "recallException") expect(value.length, `${n.slug}.${key}`).toBeGreaterThan(50);
