const root = new URL("../../../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
const sha = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
interface BeforeRow {
  recordId: string; inventoryKind: string; conceptId: string; questionVariantId: string; nodeId?: string;
  questionSha256?: string; nodeSha256?: string; exactDefinition: unknown; currentDefinitionMatch: boolean;
  source: { file: string; export: string };
  allSourceContexts: Array<{ header: unknown; headerSha256: string; precedingNodes: unknown[]; origins: Array<{ file: string; export: string }> }>;
}
interface LintReport { variantId: string; caseId: string; profileId: string | null; metrics: { completeAuthoredRationales: boolean }; findings: unknown[] }
const packet = JSON.parse(read("docs/research/question-intraop-endoscopic-upper-gi-hemostasis-20261112.json")) as {
  assignment: { id: string; slug: string; exactInventoryRecordIds: { live: string[]; retained: string[]; authoring: string[] } };
  before: BeforeRow[]; audit: Array<{ recordId: string; verdict: string | null; planningDisposition: string | null; beforeSha256: string }>;
  counts: { inventoryRecords: number; kept: number; heldOrSupersededPlanningRecords: number; additiveRewrites: number; retireAndReplace: number; newDecisions: number };
  freeze: { clinicalApprovals: Array<{ reviewer: string; approvedQuestionVariantIds: string[]; questions: Array<{ questionVariantId: string; questionSha256: string }> }>; currentLive: unknown[]; sourceFreezeReceipts: unknown[] };
  reviewReferences: Array<{ path: string; fileSha256: string }>;
  exportsSnapshot: Record<string, unknown>;
  cueLint: { version: string; contexts: number; variantCount: number; findings: unknown[]; suppressions: unknown[]; reports: LintReport[] };
  proposedItems: Array<{ nodeId: string; questionVariantId: string; exactAfterSha256: string; exactQuestionSha256: string }>;
  revisionRound1: {
    round: number;
    reviewInput: { path: string; sha256: string; records: Array<{ id: string; nodeId: string; verdict: string;
      clarityIssues: string[]; cues: Array<{ phrase: string; why: string }>; fairness: string[]; suggestions: string[] }> };
    reviewedSnapshot: { I16_CASES: typeof authored.I16_CASES; I16_QUESTIONS: typeof authored.I16_QUESTIONS;
      I16_ITEMS: typeof authored.I16_ITEMS; I16_CONCEPTS: typeof authored.I16_CONCEPTS;
      I16_AUTHORING_CONCEPTS: typeof authored.I16_AUTHORING_CONCEPTS; I16_AUTHOR_CHECKS: typeof authored.I16_AUTHOR_CHECKS };
    frozenPass: Array<{ questionVariantId: string; nodeId: string; caseId: string; questionSha256: string;
      nodeSha256: string; visibleCaseHeaderSha256: string; precedingNodesSha256: string; wholeCaseSha256: string | null; contentVersion: string }>;
    attempts: Array<{ questionVariantId: string; nodeId: string; attemptCount: number; beforeQuestionSha256: string;
      beforeNodeSha256: string; afterQuestionSha256: string; afterNodeSha256: string }>;
