  sourceUseRules: { fullTextStored: boolean; sourceExcerptsStored: boolean; gameplayNetwork: boolean };
  excludedSourceRecords: Array<{ evidenceClaimIds: string[]; reuseStatus: string }>;
};

function objects(value: unknown, seen = new Set<object>(), out: Record<string, unknown>[] = []) {
  if (!value || typeof value !== "object" || seen.has(value)) return out;
  seen.add(value);
  if (!Array.isArray(value)) out.push(value as Record<string, unknown>);
  for (const child of Object.values(value)) if (child && typeof child === "object") objects(child, seen, out);
  return out;
}

