    const getObjects = async (file: string, name: string) => {
      const key = `${file}:${name}`;
      if (!exports.has(key)) {
        if (!modules.has(file)) modules.set(file, await import(new URL(file, root).href) as Record<string, unknown>);
        exports.set(key, objects(modules.get(file)![name]));
      }
      return exports.get(key)!;
    };
    let contexts = 0;
    for (const r of packet.before) {
      const expected = r.questionSha256 ?? r.nodeSha256;
      expect(r.currentDefinitionMatch, r.recordId).toBe(true);
      expect(sha(r.exactDefinition), r.recordId).toBe(expected);
      expect((await getObjects(r.source.file, r.source.export)).some(v => v.id === (r.nodeId ?? r.questionVariantId) && sha(v) === expected), r.recordId).toBe(true);
      expect(packet.audit.find(a => a.recordId === r.recordId)?.beforeSha256).toBe(expected);
      for (const context of r.allSourceContexts) {
        contexts += 1;
        expect(sha(context.header)).toBe(context.headerSha256);
        for (const origin of context.origins) {
          const cases = (await getObjects(origin.file, origin.export)).filter(v => Array.isArray(v.decisionNodes));
          expect(cases.some(v => {
            const { decisionNodes, ...header } = v;
            const nodes = decisionNodes as Array<{ id: string }>;
            const i = nodes.findIndex(n => n.id === r.nodeId && sha(n) === r.nodeSha256);
            return i >= 0 && sha(header) === context.headerSha256 && sha(nodes.slice(0, i)) === sha(context.precedingNodes);
